/* ========== IMPLEMENTATION ========== */

/* --- strings.c --- */

#include <stdlib.h>
#include <string.h>
#include <stdio.h>

static uint32_t fnv1a(const char *data, size_t len) {
    uint32_t hash = 2166136261u;
    for (size_t i = 0; i < len; i++) {
        hash ^= (uint8_t)data[i];
        hash *= 16777619u;
    }
    return hash;
}

void clayvm_string_table_init(clayvm_string_table_t *table) {
    memset(table, 0, sizeof(*table));
}

void clayvm_string_table_free(clayvm_string_table_t *table) {
    for (int i = 0; i < CLAYVM_STRING_TABLE_SIZE; i++) {
        clayvm_string_t *s = table->buckets[i];
        while (s) {
            clayvm_string_t *next = s->next;
            free(s->data);
            free(s);
            s = next;
        }
        table->buckets[i] = NULL;
    }
    table->count = 0;
}

clayvm_string_t *clayvm_string_find(clayvm_string_table_t *table, const char *str, size_t len) {
    uint32_t hash = fnv1a(str, len);
    uint32_t idx = hash % CLAYVM_STRING_TABLE_SIZE;
    clayvm_string_t *s = table->buckets[idx];
    while (s) {
        if (s->hash == hash && s->len == len && memcmp(s->data, str, len) == 0)
            return s;
        s = s->next;
    }
    return NULL;
}

clayvm_string_t *clayvm_string_intern(clayvm_string_table_t *table, const char *str, size_t len) {
    clayvm_string_t *existing = clayvm_string_find(table, str, len);
    if (existing) return existing;

    clayvm_string_t *s = (clayvm_string_t *)malloc(sizeof(clayvm_string_t));
    if (!s) { fprintf(stderr, "string intern: out of memory\n"); return NULL; }
    s->data = (char *)malloc(len + 1);
    if (!s->data) { return NULL; }
    memcpy(s->data, str, len);
    s->data[len] = '\0';
    s->len = len;
    s->hash = fnv1a(str, len);

    uint32_t idx = s->hash % CLAYVM_STRING_TABLE_SIZE;
    s->next = table->buckets[idx];
    table->buckets[idx] = s;
    table->count++;
    return s;
}

/* --- closures.c --- */

#include <stdlib.h>
#include <string.h>
#include <stdio.h>

int clayvm_init_closure(clayvm_closure_t *closure, uint16_t fn_index, int upvalue_count) {
    closure->function_index = fn_index;
    closure->upvalue_count = upvalue_count;
    closure->upvalues = NULL;
    if (upvalue_count > 0) {
        closure->upvalues = (clayvm_upvalue_t **)calloc((size_t)upvalue_count, sizeof(clayvm_upvalue_t *));
        if (!closure->upvalues) {
            fprintf(stderr, "closures: out of memory\n");
            return -1;
        }
    }
    return 0;
}

void clayvm_free_closure(clayvm_closure_t *closure) {
    free(closure->upvalues);
    closure->upvalues = NULL;
    closure->upvalue_count = 0;
}

clayvm_value_t clayvm_get_upvalue(clayvm_closure_t *closure, int index) {
    if (index < 0 || index >= closure->upvalue_count || !closure->upvalues[index])
        return (clayvm_value_t){0};
    return *closure->upvalues[index]->location;
}

void clayvm_set_upvalue(clayvm_closure_t *closure, int index, clayvm_value_t value) {
    if (index < 0 || index >= closure->upvalue_count || !closure->upvalues[index])
        return;
    *closure->upvalues[index]->location = value;
}

void clayvm_close_upvalue(clayvm_upvalue_t *upvalue) {
    if (!upvalue || upvalue->is_closed) return;
    upvalue->closed = *upvalue->location;
    upvalue->location = &upvalue->closed;
    upvalue->is_closed = 1;
}

/* --- native.c --- */

#include <stdlib.h>
#include <string.h>
#include <stdio.h>

void clayvm_native_table_init(clayvm_native_table_t *table) {
    table->entries = NULL;
    table->count = 0;
    table->capacity = 0;
}

void clayvm_native_table_free(clayvm_native_table_t *table) {
    free(table->entries);
    table->entries = NULL;
    table->count = 0;
    table->capacity = 0;
}

int clayvm_native_register(clayvm_native_table_t *table, const char *name,
                       clayvm_native_fn_t fn, int arity) {
    if (table->count >= table->capacity) {
        int new_cap = table->capacity < 8 ? 8 : table->capacity * 2;
        clayvm_native_entry_t *new_entries = (clayvm_native_entry_t *)realloc(
            table->entries, (size_t)new_cap * sizeof(clayvm_native_entry_t));
        if (!new_entries) {
            fprintf(stderr, "native_register: out of memory\n");
            return -1;
        }
        table->entries = new_entries;
        table->capacity = new_cap;
    }
    table->entries[table->count].name = name;
    table->entries[table->count].fn = fn;
    table->entries[table->count].arity = arity;
    return table->count++;
}

int clayvm_native_find(const clayvm_native_table_t *table, const char *name) {
    for (int i = 0; i < table->count; i++) {
        if (strcmp(table->entries[i].name, name) == 0)
            return i;
    }
    return -1;
}

int clayvm_native_call(clayvm_native_table_t *table, int index,
                   clayvm_vm_t *vm, int arg_count) {
    if (index < 0 || index >= table->count) {
        fprintf(stderr, "native_call: invalid index %d\n", index);
        return -1;
    }
    return table->entries[index].fn(vm, arg_count);
}

/* --- vm.c --- */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define READ_UINT8()  (vm->code[vm->ip++])
#define READ_INT8()   ((int8_t)vm->code[vm->ip++])
#define READ_UINT16() (vm->ip += 2, \
    (uint16_t)(vm->code[vm->ip-2] | (vm->code[vm->ip-1] << 8)))
#define READ_INT16()  ((int16_t)READ_UINT16())
#define READ_UINT32() (vm->ip += 4, \
    (uint32_t)(vm->code[vm->ip-4] | (vm->code[vm->ip-3] << 8) | \
              (vm->code[vm->ip-2] << 16) | (vm->code[vm->ip-1] << 24)))
#define READ_INT32()  ((int32_t)READ_UINT32())

static void clayvm_default_error_handler(void *vm, clayvm_error_t err, const char *msg) {
    (void)vm; (void)err;
    fprintf(stderr, "%s\n", msg);
}

static void clayvm_vm_error(clayvm_vm_t *vm, clayvm_error_t err, const char *msg) {
    vm->last_error = err;
    vm->running = 0;
    if (vm->error_handler) {
        vm->error_handler(vm->error_userdata ? vm->error_userdata : vm, err, msg);
    } else {
        clayvm_default_error_handler(vm, err, msg);
    }
}

void clayvm_vm_set_error_handler(clayvm_vm_t *vm, clayvm_error_handler_t handler, void *userdata) {
    vm->error_handler = handler;
    vm->error_userdata = userdata;
}

static void clayvm_vm_ensure_stack(clayvm_vm_t *vm, int needed) {
    if (needed <= vm->stack_capacity) return;
    int new_cap = vm->stack_capacity * 2;
    if (new_cap < needed) new_cap = needed;
    clayvm_value_t *tmp = (clayvm_value_t *)realloc(vm->stack,
        (size_t)new_cap * sizeof(clayvm_value_t));
    if (!tmp) {
        clayvm_vm_error(vm, CLAYVM_ERR_STACK_OVERFLOW, "stack realloc failed");
        return;
    }
    vm->stack = tmp;
    vm->stack_capacity = new_cap;
}

void clayvm_vm_push(clayvm_vm_t *vm, clayvm_value_t value) {
    clayvm_vm_ensure_stack(vm, vm->sp + 1);
    vm->stack[vm->sp++] = value;
}

clayvm_value_t clayvm_vm_pop(clayvm_vm_t *vm) {
    if (vm->sp <= 0) {
        clayvm_vm_error(vm, CLAYVM_ERR_STACK_UNDERFLOW, "stack underflow");
        return CLAYVM_INT64(0);
    }
    return vm->stack[--vm->sp];
}

void clayvm_vm_init(clayvm_vm_t *vm) {
    memset(vm, 0, sizeof(*vm));
    vm->stack_capacity = 4096;
    vm->stack = (clayvm_value_t *)calloc((size_t)vm->stack_capacity, sizeof(clayvm_value_t));
    vm->constants.capacity = 256;
    vm->constants.values = (clayvm_value_t *)calloc((size_t)vm->constants.capacity, sizeof(clayvm_value_t));
    vm->frame_capacity = 64;
    vm->frames = (clayvm_frame_t *)calloc((size_t)vm->frame_capacity, sizeof(clayvm_frame_t));
}

int clayvm_vm_add_constant(clayvm_vm_t *vm, clayvm_value_t value) {
    if (vm->constants.count >= vm->constants.capacity) {
        int new_cap = vm->constants.capacity * 2;
        if (new_cap < 16) new_cap = 16;
        clayvm_value_t *tmp = (clayvm_value_t *)realloc(vm->constants.values,
            (size_t)new_cap * sizeof(clayvm_value_t));
        if (!tmp) {
            clayvm_vm_error(vm, CLAYVM_ERR_CONST_OVERFLOW, "constant pool realloc failed");
            return -1;
        }
        vm->constants.values = tmp;
        vm->constants.capacity = new_cap;
    }
    int index = vm->constants.count;
    vm->constants.values[vm->constants.count++] = value;
    return index;
}

void clayvm_vm_free(clayvm_vm_t *vm) {
    if (vm->cleanup) vm->cleanup(vm);
    free(vm->stack);
    free(vm->constants.values);
    free(vm->frames);
    memset(vm, 0, sizeof(*vm));
}

void clayvm_vm_set_cleanup(clayvm_vm_t *vm, void (*cleanup)(clayvm_vm_t *vm)) {
    vm->cleanup = cleanup;
}

int handle_PUSH_CONST(clayvm_vm_t *vm) {
    uint16_t index = READ_UINT16();
    clayvm_vm_push(vm, vm->constants.values[index]);
    return 0;
}

int handle_POP(clayvm_vm_t *vm) {
    (void)clayvm_vm_pop(vm);
    return 0;
}

int handle_DUP(clayvm_vm_t *vm) {
    clayvm_value_t a = vm->stack[vm->sp - 1];
    clayvm_vm_push(vm, a);
    return 0;
}

int handle_ADD(clayvm_vm_t *vm) {
    (void)vm;
    clayvm_value_t b = clayvm_vm_pop(vm);
    clayvm_value_t a = clayvm_vm_pop(vm);
    if (b.type == CLAYVM_VAL_INT64 && a.type == CLAYVM_VAL_INT64) {
        clayvm_vm_push(vm, CLAYVM_INT64((a.as.i64 + b.as.i64)));
    } else if (b.type == CLAYVM_VAL_DOUBLE && a.type == CLAYVM_VAL_DOUBLE) {
        clayvm_vm_push(vm, CLAYVM_DOUBLE((a.as.f64 + b.as.f64)));
    } else {
        if (vm->arith_fallback) {
            vm->arith_fallback(vm, a, b, CLAYVM_OP_ADD);
        } else {
            clayvm_vm_error(vm, CLAYVM_ERR_TYPE_MISMATCH, "type mismatch in ADD");
            return -1;
        }
    }
    return 0;
}

